/**
 * tests/test-details-player-adversarial.js
 * 
 * Deep Empirical Adversarial Verification Suite for Milestone 2 Iteration 3
 * Specifically stress-testing Test 28, the Details <-> Player journey, and history handling.
 */

const fs = require('fs');
const path = require('path');

let JSDOM;
try {
  JSDOM = require('jsdom').JSDOM;
} catch (e) {
  try {
    JSDOM = require('/home/prem/monkeytype/monkeytype/node_modules/.pnpm/jsdom@27.4.0_supports-color@10.2.2/node_modules/jsdom').JSDOM;
  } catch (e2) {
    try {
      JSDOM = require('/home/prem/Documents/movies/netflix/node_modules/jsdom').JSDOM;
    } catch (e3) {
      throw new Error('JSDOM module could not be resolved: ' + e.message);
    }
  }
}

const C = {
  reset: '\x1b[0m',
  bold: '\x1b[1m',
  green: '\x1b[32m',
  red: '\x1b[31m',
  yellow: '\x1b[33m',
  cyan: '\x1b[36m',
  gray: '\x1b[90m',
};

let totalChecks = 0;
let passedChecks = 0;
let failedChecks = 0;
const defects = [];

function assert(condition, message) {
  if (!condition) {
    throw new Error(message || 'Adversarial check failed');
  }
}

function createDom(initialUrl = 'http://localhost/#home') {
  const htmlPath = path.resolve(__dirname, '../app/index.html');
  const configPath = path.resolve(__dirname, '../app/js/config.js');
  const appPath = path.resolve(__dirname, '../app/js/app.js');

  const html = fs.readFileSync(htmlPath, 'utf8');
  const dom = new JSDOM(html, { url: initialUrl, runScripts: 'outside-only' });
  const { window } = dom;

  if (!window.Element.prototype.scrollIntoView) {
    window.Element.prototype.scrollIntoView = function () {};
  }

  const configCode = fs.readFileSync(configPath, 'utf8');
  const appCode = fs.readFileSync(appPath, 'utf8');

  window.eval(configCode);
  window.eval(appCode);

  return { dom, window, app: window.CinejoyApp };
}

function sendKey(window, keyCode, key) {
  const evt = new window.KeyboardEvent('keydown', {
    key: key || (keyCode === 461 ? 'Escape' : 'Unidentified'),
    keyCode: keyCode,
    which: keyCode,
    bubbles: true,
    cancelable: true
  });
  window.dispatchEvent(evt);
}

async function runCheck(name, fn) {
  totalChecks++;
  const id = totalChecks;
  const start = Date.now();
  process.stdout.write(`  [Stress Check ${id.toString().padStart(2, '0')}] ${name} ... `);
  try {
    await fn();
    const dur = Date.now() - start;
    console.log(`${C.green}${C.bold}✔ PASS${C.reset} ${C.gray}(${dur}ms)${C.reset}`);
    passedChecks++;
  } catch (err) {
    const dur = Date.now() - start;
    console.log(`${C.red}${C.bold}✖ FAIL${C.reset} ${C.gray}(${dur}ms)${C.reset}`);
    console.error(`      ${C.red}Defect: ${err.message}${C.reset}`);
    failedChecks++;
    defects.push({ id, name, error: err.message });
  }
}

async function main() {
  console.log(`\n${C.bold}${C.cyan}========================================================================${C.reset}`);
  console.log(`${C.bold}${C.cyan}   CINEJOY-WEBOS: DETAILS <-> PLAYER ADVERSARIAL STRESS HARNESS        ${C.reset}`);
  console.log(`${C.bold}${C.cyan}========================================================================\n${C.reset}`);

  // Check 1: Mandatory Journey 1: details -> player -> exitPlayer -> details -> Back
  await runCheck('Mandatory Journey 1: details -> player -> exitPlayer -> details -> Back', async () => {
    const { app } = createDom();
    app.init();
    app.openDetails({ title: 'Test Film 1' });
    assert(app.state.currentView === 'details', 'Should be on details view');

    app.switchView('player');
    assert(app.state.currentView === 'player', 'Should be on player view');

    app.exitPlayer();
    assert(app.state.currentView === 'details', 'exitPlayer must return to details view');

    app.handleBackNavigation();
    if (app.state.currentView === 'player') {
      throw new Error('PING-PONG LOOP: Back key re-entered player view!');
    }
    assert(app.state.currentView === 'home', `Expected Back to return to 'home', got '${app.state.currentView}'`);
  });

  // Check 2: Mandatory Journey 2: movies -> details -> player -> exitPlayer -> details -> Back
  await runCheck('Mandatory Journey 2: movies -> details -> player -> exitPlayer -> details -> Back', async () => {
    const { app } = createDom('http://localhost/#movies');
    app.init();
    assert(app.state.currentView === 'movies', 'Should start on movies view');

    app.openDetails({ title: 'Interstellar', year: '2014', rating: '8.7' });
    assert(app.state.currentView === 'details', 'Should be on details view');
    assert(app.state.detailsOriginView === 'movies', `Expected detailsOriginView to be 'movies', got '${app.state.detailsOriginView}'`);

    app.switchView('player');
    assert(app.state.currentView === 'player', 'Should be on player view');

    app.exitPlayer();
    assert(app.state.currentView === 'details', 'Should return to details view');

    app.handleBackNavigation();
    if (app.state.currentView === 'player') {
      throw new Error('PING-PONG LOOP: Back key re-entered player view!');
    }
    assert(app.state.currentView === 'movies', `Expected Back to return to origin 'movies', got '${app.state.currentView}'`);
  });

  // Check 3: Mandatory Journey 3: series -> details -> related details -> player -> exitPlayer -> Back -> Back
  await runCheck('Mandatory Journey 3: series -> details -> related details -> player -> exitPlayer -> Back -> Back', async () => {
    const { app } = createDom('http://localhost/#series');
    app.init();
    assert(app.state.currentView === 'series', 'Should start on series view');

    app.openDetails({ title: 'Series Title 1' });
    assert(app.state.currentView === 'details', 'Should be on details view (item 1)');
    assert(app.state.detailsOriginView === 'series', `Expected detailsOriginView to be 'series', got '${app.state.detailsOriginView}'`);

    // Related details navigation
    app.openDetails({ title: 'Related Title 2' });
    assert(app.state.currentView === 'details', 'Should be on details view (item 2)');
    assert(app.state.detailsOriginView === 'series', 'Origin view must remain series across related details');

    app.switchView('player');
    assert(app.state.currentView === 'player', 'Should be on player view');

    app.exitPlayer();
    assert(app.state.currentView === 'details', 'Should return to details view');

    // 1st Back
    app.handleBackNavigation();
    if (app.state.currentView === 'player') {
      throw new Error('PING-PONG LOOP: 1st Back key re-entered player view!');
    }
    assert(app.state.currentView === 'series', `1st Back must escape to 'series', got '${app.state.currentView}'`);

    // 2nd Back
    app.handleBackNavigation();
    assert(app.state.currentView === 'home', `2nd Back must escape to 'home', got '${app.state.currentView}'`);

    // 3rd Back: Home exit threshold
    app.handleBackNavigation();
    assert(app.state.currentView === 'home', '3rd Back on home must stay on home');
  });

  // Check 4: Remote KeyCode 461 event dispatch across full flow
  await runCheck('Remote KeyCode 461 event dispatch throughout movies -> details -> player -> details -> movies', async () => {
    const { window, app } = createDom('http://localhost/#movies');
    app.init();

    app.openDetails({ title: 'Dune' });
    app.switchView('player');
    assert(app.state.currentView === 'player');

    // Press webOS Back key (461)
    sendKey(window, 461, 'Escape');
    assert(app.state.currentView === 'details', `Expected return to details, got ${app.state.currentView}`);

    // Press webOS Back key (461) again
    sendKey(window, 461, 'Escape');
    assert(app.state.currentView === 'movies', `Expected return to movies, got ${app.state.currentView}`);

    // Press webOS Back key (461) again
    sendKey(window, 461, 'Escape');
    assert(app.state.currentView === 'home', `Expected return to home, got ${app.state.currentView}`);
  });

  // Check 5: Real DOM button clicks: #details-play-btn and #player-back-btn
  await runCheck('Real DOM button clicks: #details-play-btn -> #player-back-btn -> Remote Back', async () => {
    const { window, app } = createDom('http://localhost/#movies');
    app.init();

    app.openDetails({ title: 'Blade Runner 2049' });
    assert(app.state.currentView === 'details');

    // Click #details-play-btn
    const playBtn = window.document.getElementById('details-play-btn');
    assert(playBtn, '#details-play-btn must exist in DOM');
    playBtn.dispatchEvent(new window.MouseEvent('click', { bubbles: true, cancelable: true }));
    assert(app.state.currentView === 'player', `Clicking play button should switch to player, got ${app.state.currentView}`);

    // Click #player-back-btn
    const playerBackBtn = window.document.getElementById('player-back-btn');
    assert(playerBackBtn, '#player-back-btn must exist in DOM');
    playerBackBtn.dispatchEvent(new window.MouseEvent('click', { bubbles: true, cancelable: true }));
    assert(app.state.currentView === 'details', `Clicking player back button should return to details, got ${app.state.currentView}`);

    // Remote Back on details
    sendKey(window, 461, 'Escape');
    assert(app.state.currentView === 'movies', `Back from details should return to movies, got ${app.state.currentView}`);
  });

  // Check 6: Search origin journey
  await runCheck('Search origin journey: search -> details -> player -> exitPlayer -> details -> Back', async () => {
    const { app } = createDom('http://localhost/#search');
    app.init();
    assert(app.state.currentView === 'search');

    app.openDetails({ title: 'Search Result Title' });
    assert(app.state.detailsOriginView === 'search', `Expected detailsOriginView to be 'search', got '${app.state.detailsOriginView}'`);

    app.switchView('player');
    app.exitPlayer();
    assert(app.state.currentView === 'details');

    app.handleBackNavigation();
    assert(app.state.currentView === 'search', `Expected return to search, got '${app.state.currentView}'`);
  });

  // Check 7: Deep related details chain (10 levels)
  await runCheck('Deep related details chain (10 levels) -> player -> exitPlayer -> Back -> Back', async () => {
    const { app } = createDom('http://localhost/#series');
    app.init();

    for (let depth = 1; depth <= 10; depth++) {
      app.openDetails({ title: `Related Series ${depth}` });
      assert(app.state.detailsOriginView === 'series', `detailsOriginView must stay 'series' at depth ${depth}`);
    }

    app.switchView('player');
    app.exitPlayer();
    assert(app.state.currentView === 'details');

    app.handleBackNavigation();
    assert(app.state.currentView === 'series', `Expected escape to series, got '${app.state.currentView}'`);

    app.handleBackNavigation();
    assert(app.state.currentView === 'home', `Expected escape to home, got '${app.state.currentView}'`);
  });

  // Check 8: 50 sequential play / exit cycles on single details view
  await runCheck('50 sequential play / exit cycles on single details view', async () => {
    const { app } = createDom('http://localhost/#movies');
    app.init();
    app.openDetails({ title: 'Stress Test Movie' });

    for (let cycle = 1; cycle <= 50; cycle++) {
      app.switchView('player');
      app.exitPlayer();
      assert(app.state.currentView === 'details', `Cycle ${cycle}: currentView must be 'details'`);
      assert(app.state.detailsOriginView === 'movies', `Cycle ${cycle}: detailsOriginView must be 'movies'`);
    }

    app.handleBackNavigation();
    assert(app.state.currentView === 'movies', `After 50 cycles, Back must return to movies, got '${app.state.currentView}'`);
  });

  // Check 9: Direct boot into #details without prior catalog view
  await runCheck('Direct boot into #details without prior catalog view safely defaults to home on Back', async () => {
    const { app } = createDom('http://localhost/#details');
    app.init();
    assert(app.state.currentView === 'details');

    app.switchView('player');
    app.exitPlayer();
    assert(app.state.currentView === 'details');

    app.handleBackNavigation();
    assert(app.state.currentView === 'home', `Expected fallback to 'home', got '${app.state.currentView}'`);
  });

  // Check 10: Direct boot into #player without prior view
  await runCheck('Direct boot into #player without prior view safely defaults to home on Back', async () => {
    const { app } = createDom('http://localhost/#player');
    app.init();
    assert(app.state.currentView === 'player');

    app.handleBackNavigation();
    assert(app.state.currentView === 'home', `Expected Back from direct player to go to 'home', got '${app.state.currentView}'`);
  });

  // Check 11: Rapid back spam within 5ms (asynchronous timer cancellation check)
  await runCheck('Rapid back spam within 5ms (focus timer cancellation stress)', async () => {
    const { app } = createDom('http://localhost/#movies');
    app.init();

    app.openDetails({ title: 'Fast Film' });
    app.switchView('player');

    // Immediately trigger exitPlayer then back navigation before the 50ms focus timer
    app.exitPlayer();
    app.handleBackNavigation();
    assert(app.state.currentView === 'movies', `Expected 'movies', got '${app.state.currentView}'`);

    // Wait 70ms to allow any pending timers to execute
    await new Promise(resolve => setTimeout(resolve, 70));

    // Focus should now belong to view-movies, NOT view-details or view-player
    const activeViewEl = app.state.focusedElement ? app.state.focusedElement.closest('.view') : null;
    if (activeViewEl) {
      assert(activeViewEl.id === 'view-movies' || activeViewEl.id === 'app-header' || !activeViewEl.id,
        `Focused element must not belong to an inactive view! Found in ${activeViewEl.id}`);
    }
  });

  // Check 12: Spatial navigation accessibility after returning to details
  await runCheck('Spatial navigation D-pad remains functional on details after returning from player', async () => {
    const { window, app } = createDom('http://localhost/#movies');
    app.init();

    app.openDetails({ title: 'Nav Test Movie' });
    app.switchView('player');
    app.exitPlayer();

    // Verify initial focus in details
    assert(app.state.focusedElement, 'An element must be focused in details view');
    const focusedInDetails = app.state.focusedElement.id;

    // Dispatch ArrowDown keydown
    sendKey(window, 40, 'ArrowDown');

    // Should not throw, focused element should be defined
    assert(app.state.focusedElement, 'Focus must remain defined after spatial navigation');
  });

  // Check 13: Defensive check: Calling exitPlayer() when NOT in player view does not corrupt state
  await runCheck('Calling exitPlayer() defensively when NOT in player view does not corrupt state', async () => {
    const { app } = createDom('http://localhost/#home');
    app.init();
    assert(app.state.currentView === 'home');

    // Accidental call while on home
    app.exitPlayer();
    assert(app.state.currentView === 'home', `Expected to remain on home, got '${app.state.currentView}'`);

    // Accidental call while on details
    app.openDetails({ title: 'Safe Film' });
    assert(app.state.currentView === 'details');
    app.exitPlayer();
    assert(app.state.currentView === 'home', `Expected return to home or safe state, got '${app.state.currentView}'`);
  });

  // Check 14: Switching views via header nav cleanly resets detailsOriginView
  await runCheck('Switching views via header nav cleanly resets detailsOriginView', async () => {
    const { app } = createDom('http://localhost/#movies');
    app.init();

    app.openDetails({ title: 'Movie 1' });
    assert(app.state.detailsOriginView === 'movies');

    // Switch to search via header nav
    app.switchView('search');
    assert(app.state.detailsOriginView === null, 'detailsOriginView must be null after navigating away');

    // Open details from search
    app.openDetails({ title: 'Search Item' });
    assert(app.state.detailsOriginView === 'search', 'New origin must be search');

    app.switchView('player');
    app.exitPlayer();
    app.handleBackNavigation();
    assert(app.state.currentView === 'search', `Must return to search, got '${app.state.currentView}'`);
  });

  // Check 15: Hashchange synchronization during playback exit
  await runCheck('Browser hashchange to #details during playback exits player safely', async () => {
    const { window, app } = createDom('http://localhost/#movies');
    app.init();

    app.openDetails({ title: 'Hash Movie' });
    app.switchView('player');
    assert(app.state.currentView === 'player');

    // User or browser triggers hash change back to #details
    window.location.hash = '#details';
    window.dispatchEvent(new window.HashChangeEvent('hashchange'));
    assert(app.state.currentView === 'details');

    // Back key must still return to movies!
    app.handleBackNavigation();
    assert(app.state.currentView === 'movies', `Expected return to movies, got '${app.state.currentView}'`);
  });

  console.log(`\n${C.bold}${C.cyan}========================================================================${C.reset}`);
  console.log(`${C.bold}► HARNESS EXECUTION SUMMARY${C.reset}`);
  console.log(`------------------------------------------------------------------------`);
  console.log(`  Total Adversarial Checks Run:  ${totalChecks}`);
  console.log(`  Passed Checks:                ${passedChecks}`);
  console.log(`  Failed Checks:                ${failedChecks}`);
  console.log(`------------------------------------------------------------------------`);

  if (failedChecks > 0) {
    console.log(`\n${C.red}${C.bold}VERDICT: REQUEST_CHANGES (${failedChecks} defects detected)${C.reset}\n`);
    process.exit(1);
  } else {
    console.log(`\n${C.green}${C.bold}VERDICT: APPROVE (ALL ${totalChecks} ADVERSARIAL STRESS CHECKS PASSED 100%)${C.reset}\n`);
    process.exit(0);
  }
}

main().catch(err => {
  console.error('Fatal runner error:', err);
  process.exit(1);
});
